/* ==========================================================================
 * `config.h` —— 由 autotools 在 `./configure` 时生成的那一份的**手写等价物**。
 *
 * 上游每个 `.c` 里都有一段
 *
 *     #ifdef HAVE_CONFIG_H
 *     #include "config.h"
 *     #endif
 *
 * 而 0.2.0 的内核不用 autotools（也没有 configure，更没有 `config.h.in` 里那几十个
 * 探测项）。可这个文件**不能省** —— `EXPORT` 就住在它里面，缺了它整个 libspeex
 * 一行都编不过（第一次试编就是这么红的：`error: expected ';' before 'void'` × 62 处）。
 *
 * ⚠️ 光有这个文件还不够：**编译时必须带 `-DHAVE_CONFIG_H`**（上游的 `DEFS = -DHAVE_CONFIG_H`
 *    就是这个作用）。忘了它的话**不会**悄悄变成"少几个开关" —— 上面那句 `EXPORT`
 *    报错会当场把构建打红，这正是我们想要的失败方式。
 *
 * 这里只定义**真正被引用到的**那些（逐条查过：见每一项后面的说明），
 * 其余探测项（`SIZEOF_*` / `PACKAGE_*` / `USE_ALLOCA` / `VAR_ARRAYS` …）**故意不定义** ——
 * 不定义就走上游的默认分支，而"上游默认"正是它自己测试得最多的那条路。
 * ========================================================================== */

#ifndef DSH_SPEEX_CONFIG_H
#define DSH_SPEEX_CONFIG_H

/*
 * `EXPORT`：上游在 Windows 上把它定义成 `__declspec(dllexport)`。
 *
 * ⚠️ 这里故意定义成**空的**：0.2.0 的 DLL 导出表是**由接口定义生成的 `.def` 显式列出来的**
 *    （见 `tools/build-windows-dll.sh` 那段"为什么不用 --export-all-symbols"）。
 *    让 libspeex 自己往外导符号，等于在内核的导出表里塞进 70 多个不属于接口定义的名字 ——
 *    那不只是一次泄漏，它会把"接口定义只有一处来源"这件事在二进制层面弄脏。
 */
#define EXPORT

/*
 * 浮点还是定点：**必须二选一**（`arch.h` 里有一句 `#error` 等着），选哪个由这里定。
 *
 * ── 选定：浮点。三个理由，都是实测出来的（实测结果见 `native/vendor/README.md`）────────────
 *   ① 它是**上游的默认**（`configure` 不加 `--enable-fixed-point` 就是它），
 *      也是**第三方裁判**那份官方 `libspeex.dll`（SpeexSharp 1.2.0 带的）的配置 ——
 *      实测这一份解出来的 PCM 与裁判的**相关系数 1.0000**（平均样本差 0.361、
 *      最大 2 / 满量程 32768），也就是说"同一个实现，只差编译器把浮点算成什么样"；
 *   ② 0.2.0 的目标平台（Windows x64/arm64、Android/iOS/HarmonyOS 手机）**都有 FPU**，
 *      "没有浮点单元所以要用定点"那个前提在这一版不成立；
 *   ③ 音质：官方文档说定点比浮点略低，实测也对得上 —— 换成定点之后与裁判的
 *      相关系数是 **0.9999**、平均样本差 **63**（最大 588）。
 *      两者都是"同一段音频"，但浮点近 175 倍，没有理由为了一个用不上的可复现性去付它。
 *
 * ⚠️ 定点**没有被删掉**，它只是一行宏：真要给无 FPU 的目标编，把下面这行换成
 *    `#define FIXED_POINT` 即可 —— **但必须重新跑一次 `test_audio` ⑧**，
 *    那一条钉着 PCM 的哈希，换配置它就会当场变红（这正是它存在的意义）。
 * ⚠️ 顺带记一条：**连裁判自己都不是逐位可复现的** —— 那份 MSVC 编的 DLL 与这份
 *    GCC 编的浮点版，最大样本差是 2。所以"逐位跨编译器一致"这件事在浮点下做不到，
 *    谁想要它就得选定点；这一条是**取舍**，不是疏漏。
 */
#define FLOATING_POINT

/*
 * 不定义 `DISABLE_ENCODER` / `DISABLE_VBR` / `DISABLE_WIDEBAND`：
 *   · 前两个能省一点体积（这一版只解不编），但它们会改变**上游编译出来的形态**，
 *     而"能不能省"要靠一次单独的逐字节对照来证明 —— 那是另一件事，不混在第一次接线里做；
 *   · `DISABLE_WIDEBAND` **绝不能用**：宽带（16 kHz）是 LDOCE5 那类词典录音的形态。
 */

#endif /* DSH_SPEEX_CONFIG_H */
